        const targetPath = routeMatch[1];
        const remainder = routeMatch[2] || '';
        const productionUrl = `${baseUrl}/webhook/${targetPath}`;
        const testUrl = `${baseUrl}/webhook-test/${targetPath}`;

        output.route = 'subWorkflow';
